#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> raw(n);
    int totalCells = 0;
    for(int i=0;i<n;i++){
        cin >> ksz[i];
        raw[i].resize(ksz[i]);
        for(int j=0;j<ksz[i];j++) cin >> raw[i][j].first >> raw[i][j].second;
        totalCells += ksz[i];
    }

    struct Orient {
        vector<pair<int,int>> cells;
        int w, h, r, f;
    };

    auto transform = [](vector<pair<int,int>>& src, int f, int r) -> vector<pair<int,int>> {
        vector<pair<int,int>> res;
        for(auto [x,y]: src){
            int tx=x, ty=y;
            if(f) tx=-tx;
            for(int rr=0;rr<r;rr++){int nx=-ty,ny=tx;tx=nx;ty=ny;}
            res.push_back({tx,ty});
        }
        int mx=INT_MAX, my=INT_MAX;
        for(auto&[x,y]:res){mx=min(mx,x);my=min(my,y);}
        for(auto&[x,y]:res){x-=mx;y-=my;}
        sort(res.begin(),res.end());
        return res;
    };

    vector<vector<Orient>> orients(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++){
            for(int r=0;r<4;r++){
                auto tr = transform(raw[i], f, r);
                if(seen.insert(tr).second){
                    int mxx=0,myy=0;
                    for(auto [x,y]:tr){mxx=max(mxx,x);myy=max(myy,y);}
                    orients[i].push_back({tr,mxx+1,myy+1,r,f});
                }
            }
        }
    }

    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return ksz[a]>ksz[b];});

    int bestArea=INT_MAX;
    vector<int> bx(n),by(n),br(n),bf(n);
    int bestW=0,bestH=0;

    auto t0=chrono::steady_clock::now();
    int sq=max(1,(int)ceil(sqrt((double)totalCells)));

    for(int W=max(1,sq/3);W<=min(totalCells*3,sq*5);W++){
        if(chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now()-t0).count()>8500)break;
        int Hmax=totalCells/W+200;
        if(Hmax<1)continue;
        if((long long)W*Hmax>2000000LL) Hmax=2000000/W;
        if(Hmax<1)continue;

        vector<int> grid(W*Hmax,0);
        vector<int> px(n),py(n),pr(n),pf(n);
        int curH=0;
        bool ok=true;
        for(int idx=0;idx<n&&ok;idx++){
            int i=order[idx];
            int bs=INT_MAX;int bxx=-1,byy=-1,boi=-1;
            for(int oi=0;oi<(int)orients[i].size();oi++){
                auto&o=orients[i][oi];
                if(o.w>W)continue;
                for(int x=0;x<=W-o.w;x++){
                    for(int y=0;y+o.h<=Hmax;y++){
                        bool fit=true;
                        for(auto&[cx,cy]:o.cells)if(grid[(x+cx)*Hmax+(y+cy)]){fit=false;break;}
                        if(fit){
                            int nh=max(curH,y+o.h);
                            if((long long)W*nh<bestArea){
                                int sc=nh*10000+y*100+x;
                                if(sc<bs){bs=sc;bxx=x;byy=y;boi=oi;}
                            }
                            break;
                        }
                    }
                }
            }
            if(boi<0){ok=false;break;}
            auto&o=orients[i][boi];
            px[i]=bxx;py[i]=byy;pr[i]=o.r;pf[i]=o.f;
            for(auto&[cx,cy]:o.cells){grid[(bxx+cx)*Hmax+(byy+cy)]=1;curH=max(curH,byy+cy+1);}
        }
        if(ok&&(long long)W*curH<bestArea){bestArea=W*curH;bestW=W;bestH=curH;bx=px;by=py;br=pr;bf=pf;}
    }

    if(bestArea==INT_MAX){
        int W=0,H=0;int cx=0;
        for(int i=0;i<n;i++){W+=orients[i][0].w;H=max(H,orients[i][0].h);}
        bestW=W;bestH=H;
        cx=0;
        for(int i=0;i<n;i++){bx[i]=cx;by[i]=0;br[i]=orients[i][0].r;bf[i]=orients[i][0].f;cx+=orients[i][0].w;}
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bx[i]<<" "<<by[i]<<" "<<br[i]<<" "<<bf[i]<<"\n";
}
